public void doPermute(int[] nums, int start, List<List<Integer>> result) {
    if (start == nums.length - 1) {
        result.add(new ArrayList<>(Arrays.asList(nums)));
        return;
    }

    for (int i = start; i < nums.length; i++) {
        swap(nums, start, i);
        doPermute(nums, start + 1, result);
        swap(nums, start, i);
    }
}
