public int findLargestSubstring(List<String> strings) {
    int maxLength = 0;
    for (String str : strings) {
        maxLength = Math.max(maxLength, findLargestSubstringLength(str));
        maxLength = Math.max(maxLength, findLargestSubstringLength(String.valueOf(str).reverse()));
    }
    return maxLength;
}

private int findLargestSubstringLength(String str) {
    int maxLength = 0;
    for (int i = 1; i <= str.length() / 2; i++) {
        if (str.length() % i != 0) {
            continue;
        }
        if (substringHelper(str, i, 0)) {
            maxLength = i;
        }
    }
    return maxLength;
}

private boolean substringHelper(String str, int subLength, int start) {
    for (int end = start + subLength; end < str.length(); end += subLength) {
        if (!str.substring(start, end).equals(str.substring(end, start + subLength).reverse()) {
            return false;
        }
    }
    return true;
}
