public boolean splitArraySameAverage(int[] nums) {
    Arrays.sort(nums);
    int totalSum = Arrays.stream(nums).sum();
    int targetSum = totalSum / 2;
    return findSubarray(nums, 0, nums.length - 1, targetSum);
}

private boolean findSubarray(int[] nums, int start, int end, int targetSum) {
    if (end - start + 1 < 2) return false;
    int subSum = 0;
    for (int i = start; i <= end; i++) {
        subSum += nums[i];
        if (subSum == targetSum) return true;
        if (subSum > targetSum) return false;
        if (i == end) return findSubarray(nums, start, i - 1, targetSum);
    }
    return false;
}
```

