    public static int kthFactor(int n, int k) {
        if (n < 1 || k < 1 || k > n) {
            return -1;
        }

        int factor = 2;
        int count = 0;

        while (factor * factor <= n) {
            if (n % factor == 0) {
                if (factor == n / factor) {
                    count++;
                } else {
                    count += 2;
                }
                if (count == k) {
                    return factor;
                }
            }
            factor++;
        }

        return -1;
    }
}
