import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class SteppingNumbersFinder {
    /**
     * Finds all stepping numbers in the range [low, high] where a stepping number is defined as a number where each digit is either one more or one less than the adjacent digit.
     *
     * @param low The lower bound of the range.
     * @param high The upper bound of the range.
     * @return A list of stepping numbers within the range [low, high] sorted in ascending order.
     */
    public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> result = new ArrayList<>();
        for (int i = 1; i <= 9; i++) {
            List<Integer> numbers = new ArrayList<>();
            helper(i, numbers, low, high);
            result.addAll(numbers);
        }
        result.sort(Integer::compare);

        // Filter the result to include only numbers in the given range
        result = result.stream().filter(num -> num >= low && num <= high).collect(Collectors.toList());
        return result;
    }

    private static void helper(int num, List<Integer> numbers, int low, int high) {
        if (num >= low && num <= high) {
            numbers.add(num);
        }

        int lastDigit = (int) (num % 10);
        if (lastDigit > 0) {
            helper(num * 10 + (lastDigit - 1), numbers, low, high);
        }
        if (lastDigit < 9) {
            helper(num * 10 + (lastDigit + 1), numbers, low, high);
        }
    }
}
